SELECT o.id, o.symbol, o.status, o.started_at, o.last_evidence_at, o.latest_signal_id, o.evidence_score, o.opportunity_health, o.five_minute_decision, o.one_hour_decision, o.execution_source, o.recommended_position_percent, o.decision_code, LEFT(o.decision_explanation, 1200) AS decision_explanation, o.executed_at FROM execution_opportunity o WHERE o.latest_signal_id IN (156723,159408,165412,167668,171589,176710) OR (o.symbol IN ('EGLDUSDT','XRPUSDT','DOGEUSDT','SHIBUSDT','ACEUSDT') AND o.executed_at BETWEEN '2026-10-11 20:50:00' AND '2026-10-12 10:00:00') ORDER BY o.executed_at LIMIT 40